package controlsys

import (
	"errors"
	"runtime"
	"testing"

	"plantcontrol.org/v1/gonum/mat"
)

type dareHewerGainCase struct {
	name, arch       string
	n, m             int
	A, B, Q, R, S, E []float64
}

func (tc dareHewerGainCase) dense() (A, B, Q, R, S, E *mat.Dense) {
	A, B = mat.NewDense(tc.n, tc.n, tc.A), mat.NewDense(tc.n, tc.m, tc.B)
	Q, R = mat.NewDense(tc.n, tc.n, tc.Q), mat.NewDense(tc.m, tc.m, tc.R)
	if tc.S != nil {
		S = mat.NewDense(tc.n, tc.m, tc.S)
	}
	if tc.E != nil {
		E = mat.NewDense(tc.n, tc.n, tc.E)
	}
	return
}

